"""Network settings for all Hugging Face Hub traffic of the nightly sync job."""

import logging

import httpx2
from huggingface_hub import HfApi
from huggingface_hub.utils import _http as hf_http

logger = logging.getLogger("app.network")

TIMEOUT = httpx2.Timeout(60.0, connect=5.0)
JOB_HEADERS = {"X-Acme-Job": "nightly-sync"}


def _enforce_timeout(request: httpx2.Request) -> None:
    # huggingface_hub passes `timeout=None` explicitly in many calls (e.g. `model_info`), which in httpx2
    # disables every timeout instead of falling back to the client's. Restore ours in that case.
    timeout = request.extensions.get("timeout")
    if timeout is None or all(value is None for value in timeout.values()):
        request.extensions = {**request.extensions, "timeout": TIMEOUT.as_dict()}


def configure_hub_http(transport=None) -> None:
    def client_factory() -> httpx2.Client:
        return httpx2.Client(
            # Keep huggingface_hub's own hook (offline mode, request ids, debug logging).
            event_hooks={"request": [_enforce_timeout, hf_http.hf_request_event_hook]},
            follow_redirects=True,
            timeout=TIMEOUT,
            headers=JOB_HEADERS,
            transport=transport,
        )

    # Closes any existing shared client; the next request builds the new one from this factory.
    hf_http.set_client_factory(client_factory)


def current_revision(repo_id: str) -> str | None:
    try:
        return HfApi().model_info(repo_id, revision="main").sha
    except (httpx2.ConnectError, httpx2.TimeoutException) as exc:
        logger.warning("Cannot reach the Hugging Face Hub for %s: %s", repo_id, exc)
        return None

